std::optional<std::u16string_view> stockTagName(std::string_view locale,std::u16string_view key)noexcept{
  const auto row=std::ranges::lower_bound(catalogue,locale,{},&Row::locale);
  if(row==catalogue.end()||row->locale!=locale){return {};}
  const auto found=std::ranges::lower_bound(keys,key);
  if(found==keys.end()||*found!=key){return {};}return row->names[static_cast<std::size_t>(found-keys.begin())];
}
